import os
import re
from pathlib import Path
from typing import Optional, List

import pytest

REPO_DIR = os.getenv("REPO_DIR", "/workspace/metabase")
ANALYTICS_FILE = os.path.join(REPO_DIR, "frontend/src/metabase/lib/analytics.ts")


def read_file(path: str) -> str:
    """Read file contents."""
    with open(path, "r", encoding="utf-8") as f:
        return f.read()


def extract_interface_body(content: str, interface_name: str) -> Optional[str]:
    """
    Extract the body of an interface definition.
    Returns the content between opening and closing braces.
    """
    pattern = rf"interface\s+{re.escape(interface_name)}\s*\{{(.*?)\}}"
    match = re.search(pattern, content, re.DOTALL)
    if match:
        return match.group(1)
    return None


def extract_type_definition(content: str, type_name: str) -> Optional[str]:
    """
    Extract the body of a type definition.
    Returns the content after 'type TypeName ='.
    """
    pattern = rf"type\s+{re.escape(type_name)}\s*=\s*(.*?)(?=;|\n(?!\s))"
    match = re.search(pattern, content, re.DOTALL)
    if match:
        return match.group(1)
    return None


def check_field_in_interface(interface_body: str, field_name: str) -> bool:
    """
    Check if a field exists in an interface/type body.
    Looks for 'field_name' optionally followed by '?' and then ':'
    """
    if interface_body is None:
        return False
    pattern = rf"\b{re.escape(field_name)}\s*\??\s*:"
    return bool(re.search(pattern, interface_body))


def extract_all_fields(interface_body: str) -> List[str]:
    """
    Extract all field names from an interface/type body.
    Handles snake_case and camelCase field names.
    """
    if interface_body is None:
        return []
    pattern = r"\b([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\??\s*:"
    matches = re.findall(pattern, interface_body)
    return matches


def is_snake_case(name: str) -> bool:
    """
    Check if a name is in snake_case.
    Valid: lowercase letters, digits, underscores, no camelCase.
    """
    return bool(re.match(r"^[a-z0-9_]+$", name))


def check_interface_field_types(interface_body: str, field_name: str, expected_type: str) -> bool:
    """
    Check if a field in an interface has the expected type.
    """
    if interface_body is None:
        return False
    pattern = rf"\b{re.escape(field_name)}\s*\??\s*:\s*{re.escape(expected_type)}"
    return bool(re.search(pattern, interface_body))


class TestAnalyticsEventDefinitions:
    """Test suite for analytics event definitions."""

    @pytest.fixture(scope="class")
    def analytics_content(self):
        """Load analytics.ts file."""
        assert os.path.exists(
            ANALYTICS_FILE
        ), f"File {ANALYTICS_FILE} does not exist"
        return read_file(ANALYTICS_FILE)

    # =========== AnalyticsEvent Interface Tests ===========

    def test_analytics_event_interface_exists(self, analytics_content):
        """Verify AnalyticsEvent interface is defined."""
        assert (
            "interface AnalyticsEvent" in analytics_content
        ), "AnalyticsEvent interface not found"

    def test_analytics_event_has_event_name_field(self, analytics_content):
        """Verify AnalyticsEvent has event_name field of type string."""
        body = extract_interface_body(analytics_content, "AnalyticsEvent")
        assert body is not None, "Could not extract AnalyticsEvent interface body"
        assert check_field_in_interface(
            body, "event_name"
        ), "event_name field not found in AnalyticsEvent"
        assert check_interface_field_types(
            body, "event_name", "string"
        ), "event_name should be of type string"

    def test_analytics_event_has_payload_field(self, analytics_content):
        """Verify AnalyticsEvent has payload field of type Record<string, unknown>."""
        body = extract_interface_body(analytics_content, "AnalyticsEvent")
        assert body is not None, "Could not extract AnalyticsEvent interface body"
        assert check_field_in_interface(
            body, "payload"
        ), "payload field not found in AnalyticsEvent"
        assert (
            "Record<string, unknown>" in body
