        pattern = r"(type|interface|export|const)\s+\w*.*dashboard_viewed"
        assert re.search(
            pattern, analytics_content, re.IGNORECASE
        ), "dashboard_viewed event definition not found"

    def test_dashboard_viewed_payload_has_required_fields(self, analytics_content):
        """
        Verify dashboard_viewed event has payload with dashboard_id, view_duration_ms, card_count.
        Searches for these fields within any type or interface that relates to dashboard_viewed.
        """
        required_fields = ["dashboard_id", "view_duration_ms", "card_count"]

        # Extract a reasonable context around dashboard_viewed
        match = re.search(
            r"dashboard_viewed.*?(?=\n(?:type|interface|export|const)|$)",
            analytics_content,
            re.DOTALL | re.IGNORECASE,
        )
        if match:
            context = match.group(0)
        else:
            context = analytics_content

        for field in required_fields:
